      hu: "Xaisomboun, más néven Anouvong, Laosz legfiatalabb tartományának fővárosa. A hegyvidéki táj vad és érintetlen.",
      ro: "Xaisomboun, cunoscut și sub numele de Anouvong, este capitala celei mai tinere provincii din Laos. Peisajul montan este sălbatic și neatins.",
