  {
    id: "nong-khiaw-cities-v2",
    type: "city",
    parent: "LA-LP",
    coords: [102.6167, 20.5667],
    name: {
      de: "Nong Khiaw",
      hu: "Nong Khiaw",
      ro: "Nong Khiaw",
      en: "Nong Khiaw"},
    image: "/poi-images/nong-khiaw-cities-v2.webp",
    description: {
      de: "Nong Khiaw liegt malerisch am Fluss Nam Ou, umgeben von Kalksteinfelsen. Es ist ein beliebtes Ziel für Outdoor-Aktivitäten.",
      hu: "Nong Khiaw festői környezetben fekszik a Nam Ou folyó partján, mészkősziklák ölelésében. Népszerű szabadtéri tevékenységek célpontja.",
      ro: "Nong Khiaw este situat pitoresc pe râul Nam Ou, înconjurat de stânci de calcar. Este o destinație populară pentru activități în aer liber.",
      en: "Nong Khiaw is picturesquely situated on the Nam Ou River, surrounded by limestone cliffs. It is a popular destination for outdoor activities."
    },
    descriptionAdvanced: {
      de: "Nong Khiaw, manchmal auch Nong Khiao geschrieben, ist eine kleine Stadt im Distrikt Nong Khiaw der Provinz Luang Prabang im Norden von Laos. Sie liegt malerisch am Fluss Nam Ou, einem wichtigen Nebenfluss des Mekong, der hier eine grüne Schlucht zwischen senkrechten Kalksteinwänden geschnitten hat. Wahrzeichen sind die alte und die neue Brücke über den Fluss sowie Aussichtspunkte wie Pha Daeng und der „100 Waterfalls“-Wanderweg auf den umliegenden Bergen. Vom kleinen Bootsanleger aus starten regelmäßige Boote nach Muang Ngoi Neua, einem noch ruhigeren Dorf flussaufwärts ohne Straßenanschluss. Die Region war während des Bürgerkriegs umkämpft, und in der Nähe befinden sich die Pha Tok-Höhlen, in denen Zivilisten und Kämpfer Schutz vor amerikanischen Bombenangriffen suchten.",
      hu: "Nong Khiaw, néha Nong Khiao írásmóddal, kis város a Luangprabang tartományba tartozó Nong Khiaw járásban, Észak-Laoszban. Festői helyen fekszik a Nam Ou folyó partján, amely a Mekong egyik legfontosabb mellékfolyója, és itt zöld szurdokot vágott függőleges mészkőfalak közé. Jelképei a régi és új híd a folyó felett, valamint a kilátópontok, mint a Pha Daeng és a környező hegyekre vezető „Száz Vízesés” túraút. A kis kikötőből rendszeres csónakok indulnak Muang Ngoi Neua felé, egy még csendesebb, közúton nem elérhető falu irányába. A térség a polgárháború idején harcok színtere volt, és a közelben találhatók a Pha Tok-barlangok, ahol civilek és katonák kerestek menedéket az amerikai bombázások elől, amelyek lakosokat sebesítettek meg.",
      ro: "Nong Khiaw, scris uneori și Nong Khiao, este un orășel din districtul Nong Khiaw al provinciei Luang Prabang, în nordul Laosului. Este situat pitoresc pe râul Nam Ou, un afluent important al Mekongului, care a săpat aici un defileu verde între pereți verticali de calcar. Simboluri ale localității sunt podul vechi și cel nou peste râu, precum și puncte de belvedere precum Pha Daeng și traseul „100 de Cascade” pe munții din jur. Din micul debarcader pleacă bărci regulate spre Muang Ngoi Neua, un sat și mai liniștit, fără acces rutier. Regiunea a fost teatru de lupte în timpul războiului civil, iar în apropiere se află peșterile Pha Tok, unde civili și combatanți s-au adăpostit de bombardamentele americane care lăsau urme grele.",
      en: "Nong Khiaw, sometimes spelled Nong Khiao, is a small town in Nong Khiaw District of Luang Prabang Province in northern Laos. It sits dramatically on the Nam Ou River, an important tributary of the Mekong, which has carved a green gorge between sheer limestone cliffs. Local landmarks include the old and new bridges across the river, viewpoints such as Pha Daeng and the so-called Hundred Waterfalls trekking trail on the surrounding mountains. From the small boat landing, regular long-tail boats run upstream to Muang Ngoi Neua, an even quieter village without road access. The area was contested during the civil war and the nearby Pha Tok caves sheltered civilians and fighters from heavy American bombing campaigns that left scars throughout the river valley."
    },
    facts: {
      de: [
        "Liegt am Fluss Nam Ou.",
        "Beliebt für Outdoor-Aktivitäten."
      ],
      hu: [
        "A Nam Ou folyó partján fekszik.",
        "Népszerű a szabadtéri tevékenységek miatt."
      ],
      ro: [
        "Situat pe râul Nam Ou.",
        "Popular pentru activități în aer liber."
      ],
      en: [
        "Located on the Nam Ou River.",
        "Popular for outdoor activities."
      ]
    },
    factsAdvanced: {
      en: [
        "Picturesque town situated on both banks of the Nam Ou River in northern Laos.",
        "Surrounded by incredibly steep and dramatic limestone karst rock formations.",
        "The high concrete Nong Khiaw bridge visually connects the two sides of the town.",
        "A highly popular destination for outdoor activities like rock climbing and trekking.",
        "Features several accessible caves, notably the Pha Tok cave used during wartime.",
        "Riverboat travel along the Nam Ou remains a major mode of regional transport."
      ],
      de: [
        "Malerische Stadt an beiden Ufern des Nam Ou Flusses im Norden von Laos.",
        "Umgeben von unglaublich steilen und dramatischen Kalksteinfelsformationen.",
        "Die hohe Betonbrücke von Nong Khiaw verbindet visuell die beiden Stadtteile.",
        "Ein sehr beliebtes Ziel für Outdoor-Aktivitäten wie Klettern und Trekking.",
        "Verfügt über zugängliche Höhlen, insbesondere die im Krieg genutzte Pha Tok Höhle.",
        "Die Fahrt mit dem Flussboot bleibt ein wichtiges regionales Transportmittel."
      ],
      hu: [
        "Festői szépségű város a Nam Ou folyó két partján, Laosz északi részén.",
        "Hihetetlenül meredek és drámai mészkőkarszt sziklaalakzatok veszik körül.",
        "A magas, betonból készült Nong Khiaw híd vizuálisan köti össze a város két oldalát.",
        "Kifejezetten népszerű úti cél szabadtéri tevékenységekhez, mint a sziklamászás és a túrázás.",
        "Számos látogatható barlangja van, köztük a háború idején használt Pha Tok-barlang.",
        "A Nam Ou folyón történő hajózás továbbra is a regionális közlekedés egyik fő módja."
      ],
      ro: [
        "Oraș pitoresc situat pe ambele maluri ale râului Nam Ou din nordul statului Laos.",
        "Înconjurat de formațiuni de rocă calcaroasă uimitor de abrupte și dramatice.",
        "Podul înalt de beton Nong Khiaw conectează vizual cele două părți ale orașului.",
        "O destinație extrem de populară pentru activități în aer liber.",
        "Prezintă peșteri accesibile, în special peștera Pha Tok folosită în timpul războiului.",
        "Călătoria cu barca pe Nam Ou rămâne un mod major de transport regional."
      ]
    }, image: "/poi-images/nong-khiaw-cities-v2.webp"},
  {
    id: "viengxay-cities-v2",
    type: "city",
    parent: "LA-HO",
    coords: [104.2167, 20.4000],
    name: {
      de: "Viengxay",
      hu: "Viengxay",
      ro: "Viengxay",
      en: "Viengxay"},
    image: "/poi-images/viengxay-cities-v2.webp",
    description: {
      de: "Viengxay ist berühmt für seine Karsthöhlen, die während des Vietnamkriegs als Hauptquartier der Pathet Lao dienten.",
      hu: "Viengxay híres a karsztbarlangjairól, amelyek a Pathet Lao főhadiszállásaként szolgáltak a vietnámi háború alatt.",
      ro: "Viengxay este renumit pentru peșterile sale carstice, care au servit drept sediu pentru Pathet Lao în timpul războiului din Vietnam.",
      en: "Viengxay is famous for its karst caves, which served as the headquarters of the Pathet Lao during the Vietnam War."
    },
    descriptionAdvanced: {
      de: "Viengxay liegt in der Provinz Houaphanh im äußersten Nordosten von Laos, nahe der Grenze zu Vietnam und etwa 30 Kilometer östlich von Xam Neua. Der Ort ist berühmt für ein riesiges Höhlensystem aus mehr als 480 natürlichen Karsthöhlen, das während des Indochinakriegs zwischen 1964 und 1973 als geheime unterirdische Hauptstadt der Pathet-Lao-Bewegung diente. Schätzungsweise lebten zeitweise rund 23.000 Menschen, darunter politische Führer, Soldaten, Familien und ganze Schulen, in den Höhlen, um den massiven amerikanischen Luftangriffen zu entgehen. Heute können einige der wichtigsten Höhlen, etwa die ehemaligen Quartiere von Kaysone Phomvihane, Souphanouvong und Khamtay Siphandone, im Rahmen geführter Touren mit Audioführer besichtigt werden. Die Anlage gilt heute als Mahnmal.",
      hu: "Viengxay Houaphanh tartományban, Laosz északkeleti szegletében fekszik, közel a vietnámi határhoz és mintegy 30 kilométerre keletre Xam Neuától. A helyet egy hatalmas, több mint 480 természetes karsztbarlangból álló rendszer tette híressé, amely az indokínai háború idején, 1964 és 1973 között a Pathet Lao mozgalom titkos földalatti fővárosaként szolgált. Becslések szerint időszakosan mintegy 23 ezer ember élt a barlangokban, köztük politikai vezetők, katonák, családok és egész iskolák, hogy elkerüljék a hatalmas amerikai légicsapásokat. Ma néhány fontos barlang, például Kaysone Phomvihane, Souphanouvong és Khamtay Siphandone egykori szállásai vezetett, audioguide-os túrákon tekinthetők meg. Az együttest ma nemzeti emlékhelyként is kezelik az országban.",
      ro: "Viengxay se află în provincia Houaphanh, în extremitatea nord-estică a Laosului, aproape de granița cu Vietnamul, la aproximativ 30 de kilometri est de Xam Neua. Localitatea este celebră pentru un imens sistem de peșteri format din peste 480 de cavități carstice naturale, care a servit, în timpul războiului din Indochina, între 1964 și 1973, drept capitală subterană secretă a mișcării Pathet Lao. Se estimează că, în anumite perioade, în peșteri trăiau circa 23.000 de oameni, printre care lideri politici, soldați, familii și școli întregi, pentru a se feri de bombardamentele masive americane. Astăzi, unele peșteri importante, precum fostele cartiere ale lui Kaysone Phomvihane, Souphanouvong și Khamtay Siphandone, pot fi vizitate cu ghid audio. Complexul este astăzi un memorial al țării.",
      en: "Viengxay lies in Houaphanh Province in the far northeast of Laos, close to the Vietnamese border and about 30 kilometres east of Xam Neua. The town is famous for a vast cave system of more than 480 natural karst caves which served as the secret underground capital of the Pathet Lao movement during the Indochina War between 1964 and 1973. At its peak it is estimated that around 23,000 people lived in the caves, among them political leaders, soldiers, families and entire schools, sheltering from the massive American bombing campaigns. Today several of the most important caves, including the former quarters of Kaysone Phomvihane, Souphanouvong and Khamtay Siphandone, can be visited on guided audio tours. The complex now serves as a national memorial in Laos."
    },
    facts: {
      de: [
        "Bekannt für Karsthöhlen.",
        "Hauptquartier der Pathet Lao."
      ],
      hu: [
        "Karsztbarlangjairól ismert.",
        "A Pathet Lao főhadiszállása."
      ],
      ro: [
        "Cunoscut pentru peșterile carstice.",
        "Sediul central al Pathet Lao."
      ],
      en: [
        "Known for karst caves.",
        "Headquarters of the Pathet Lao."
      ]
    },
    factsAdvanced: {
      en: [
        "Located in Houaphanh Province, commonly known as the 'Hidden City' during the war.",
        "Features an extensive network of natural caves used extensively by the Pathet Lao.",
        "The caves historically housed entire hospitals, schools, and military offices.",
        "Surrounded by dramatic karst formations that naturally protected the settlement.",
        "Relatively isolated near the Vietnamese border, requiring rugged overland travel.",
        "Remains a powerful symbol of Lao revolutionary history and resilience."
      ],
      de: [
        "Gelegen in der Provinz Houaphanh, während des Krieges als 'Verborgene Stadt' bekannt.",
        "Verfügt über ein ausgedehntes Höhlennetzwerk, das von den Pathet Lao genutzt wurde.",
        "Die Höhlen beherbergten historisch ganze Krankenhäuser, Schulen und Militärbüros.",
        "Umgeben von dramatischen Karstformationen, die die Siedlung auf natürliche Weise schützten.",
        "Relativ isoliert nahe der vietnamesischen Grenze, nur über unwegsame Straßen erreichbar.",
        "Bleibt ein starkes Symbol der laotischen Revolutionsgeschichte und Widerstandsfähigkeit."
      ],
      hu: [
        "Houaphanh tartományban található, a háború alatt 'Rejtett városként' volt ismert.",
        "Kiterjedt természetes barlangrendszerrel rendelkezik, melyet a Pathet Lao használt.",
        "A barlangokban történelmileg komplett kórházak, iskolák és katonai hivatalok működtek.",
        "Drámai karsztképződmények veszik körül, amelyek természetes védelmet nyújtottak a településnek.",
        "Viszonylag elszigetelt a vietnámi határ közelében, megközelítése rögös hegyi utakon lehetséges.",
        "A laoszi forradalmi történelem és ellenálló képesség erőteljes szimbóluma maradt."
      ],
      ro: [
        "Situat în provincia Houaphanh, cunoscut sub numele de 'Orașul ascuns' în timpul războiului.",
        "Prezintă o rețea extinsă de peșteri naturale utilizate pe scară largă de Pathet Lao.",
        "Peșterile au găzduit în istorie spitale întregi, școli și birouri militare.",
        "Înconjurat de formațiuni carstice dramatice care au protejat natural așezarea.",
        "Relativ izolat lângă granița cu Vietnam, necesitând o călătorie accidentată pe uscat.",
        "Rămâne un simbol puternic al istoriei și rezistenței revoluționare laoțiene."
      ]
    }
  }
