      de: ["Liegt auf der Route zwischen Luang Prabang und Pakbeng", "Bekannt für lebhafte Morgenmärkte", "Zentrum für den Handel mit Agrarprodukten", "Bedeutender Siedlungsort der Khmu-Minderheit"],
      hu: ["A Luang Prabang és Pakbeng közötti úton fekszik", "Élénk reggeli piacairól ismert", "Mezőgazdasági termékek kereskedelmi központja", "A khmu kisebbség jelentős települése"],
      ro: ["Situat pe ruta dintre Luang Prabang și Pakbeng", "Cunoscut pentru piețele sale matinale animate", "Centru pentru comerțul cu produse agricole", "Așezare importantă a minorității etnice Khmu"],
