      en: ["Population: approx. 45,000 (2020 est.)", "Elevation: 1,100 meters above sea level", "Area: 1,200 km²", "Distance to Phonsavan: 45 km", "Number of villages: 65", "Annual rainfall: 1,500 mm"],
