    imageHint: "Wat Taleo temple Songkhone",
    descriptionAdvanced: {
      de: "Songkhone ist ein Distrikt in der Provinz Savannakhet im Süden von Laos, nahe der Grenze zu Thailand. Die Stadt liegt am Ufer des Mekong, der hier eine wichtige Wasserstraße darstellt. Historisch war Songkhone ein bedeutender Handelsort für den Austausch von Waren zwischen Laos und Thailand. Die Architektur zeigt Einflüsse des französischen Kolonialstils, insbesondere das alte Zollhaus. Die Wirtschaft basiert auf Fischerei, Landwirtschaft (Reis, Zuckerrohr) und einem kleinen Grenzhandel. Der Songkhone-Markt ist berühmt für seine lokalen Produkte wie getrockneten Fisch und Palmzucker. Die Bevölkerung setzt sich aus Lao, Phutai und vietnamesischen Minderheiten zusammen.",
      hu: "Songkhone Savannakhet tartomány egyik körzete, amely a Mekong folyó partján fekszik. A település építészeti örökséggel rendelkezik, köztük a francia gyarmati korból származó épületekkel, mint a régi vámház. A helyi buddhista templom, Wat Songkhone, fontos zarándokhely. A lakosság hagyományosan halászattal és mezőgazdasággal foglalkozik, a Mekong bőséges halfajokat kínál. A környék híres a bambuszból készült kézműves termékekről és a selyemszövésről. A Songkhone-i fesztivál, a Boun Bang Fai, rakétafesztiválként ismert, amely az esőért való könyörgés hagyományát idézi.",
      ro: "Songkhone este un district din provincia Savannakhet, situat pe malul fluviului Mekong. Din punct de vedere cultural, zona este cunoscută pentru Festivalul Boun Bang Fai, un festival al rachetelor care marchează începutul sezonului ploios. Agricultura este predominantă, cu culturi de orez, trestie de zahăr și tutun. Pescuitul este, de asemenea, important, MeKongul oferind o gamă variată de pești. Comerțul de frontieră cu Thailanda stimulează economia locală. Populația include grupuri etnice Lao, Phutai și vietnamezi, fiecare contribuind la diversitatea culturală.",
      en: "Songkhone is a district in Savannakhet Province, southern Laos, located along the Mekong River bordering Thailand. Its economy is driven by agriculture (rice, sugarcane, tobacco), fishing, and cross-border trade. The district town features colonial-era buildings, including the old customs house, and a lively morning market. Songkhone is known for its rocket festival (Boun Bang Fai), held annually to request rain for crops. The population is ethnically mixed, with Lao, Phutai, and Vietnamese communities. The Mekong River provides a key transport route and fertile alluvial plains.",
    },
