      ro: "Nakai este un oraș în provincia Khammouane, centrul Laosului, lângă granița cu Vietnamul. Este poarta de acces către barajul Nam Theun 2 și Podișul Nakai. Economia se bazează pe agricultură, pescuit și energie hidroelectrică. Barajul Nam Theun 2 este unul dintre cele mai mari din Laos. Populația este de aproximativ 10.000. Zona este cunoscută pentru peisajele sale naturale. Populația include Lao și vietnamezi.",
