      ro: "Muang Sui este un oraș în provincia Xieng Khouang, nord-estul Laosului. Este înconjurat de formațiuni carstice și terase de orez. Economia se bazează pe agricultură, în special orez și porumb. Populația este de aproximativ 12.000. Include Lao, Hmong și Thai Dam. Orașul are o piață și mai multe temple budiste. Împrejurimile includ peșteri și cascade. Muang Sui a fost o bază militară în timpul războiului din Vietnam.",
